        "syrupy-apple": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "꿀맛사과", "en": "Syrupy Apple", "ja": "みついりりんご", "es": "Manzana Melosa", "fr": "Pomme Nectar", "de": "Saftiger Apfel"],
            texts: [
                "ko": "시럽이 가득 배어든 사과. 어떤 포켓몬에게 주면 진화한다.",
                "en": "A very syrupy apple. A certain Pokémon evolves when it is given this apple.",
                "ja": "シロップが　たっぷり　しみこんだ　リンゴ。あるポケモンに　あたえると　しんかする。",
                "es": "Una manzana empapada de sirope. Cierto Pokémon evoluciona si se le da esta manzana.",
                "fr": "Une pomme gorgée de sirop. Un certain Pokémon évolue si on la lui donne.",
                "pt": "Uma maçã encharcada de xarope. Certo Pokémon evolui ao receber esta maçã.",
                "de": "Ein Apfel, der vor Sirup trieft. Ein bestimmtes Pokémon entwickelt sich, wenn es ihn bekommt.",
                "ru": "Яблоко, пропитанное сиропом. Некоторый покемон эволюционирует, если ему его дать.",
            ]),
        "cracked-pot": Entry(appOriginalLanguages: [],
            names: ["ko": "깨진포트", "en": "Cracked Pot", "ja": "われたポット", "es": "Tetera Agrietada", "fr": "Théière Fêlée", "de": "Rissige Kanne"],
            texts: [
                "ko": "어느 특정 포켓몬을 진화시키는 이상한 포트. 깨졌지만 차는 맛있어진다.",
                "en": "A peculiar teapot that can make a certain species of Pokémon evolve. It may be cracked, but tea poured from it is delicious.",
                "ja": "ある　とくていの　ポケモンを　しんかさせる　ふしぎな　ポット。　われているが　おちゃは　おいしくなる。",
                "es": "Curiosa tetera que hace evolucionar a determinadas especies de Pokémon. Pese a estar agrietada, sirve un té exquisito.",
                "fr": "Un récipient mystérieux pouvant faire évoluer un certain Pokémon. Il est abîmé, mais on y fait du bon thé.",
                "de": "Diese spezielle Kanne löst bei einem bestimmten Pokémon die Entwicklung aus. Sie weist zwar Risse auf, aber das wirkt sich nicht negativ auf den Tee aus.",
            ]),
        "chipped-pot": Entry(appOriginalLanguages: [],
            names: ["ko": "이빠진포트", "en": "Chipped Pot", "ja": "かけたポット", "es": "Tetera Rota", "fr": "Théière Ébréchée", "de": "Löchrige Kanne"],
            texts: [
                "ko": "어느 특정 포켓몬을 진화시키는 이상한 포트. 이가 빠졌지만 차는 맛있어진다.",
                "en": "A peculiar teapot that can make a certain species of Pokémon evolve. It may be chipped, but tea poured from it is delicious.",
                "ja": "ある　とくていの　ポケモンを　しんかさせる　ふしぎな　ポット。　かけているが　おちゃは　おいしくなる。",
                "es": "Curiosa tetera que hace evolucionar a determinadas especies de Pokémon. Pese a estar rota, sirve un té exquisito.",
                "fr": "Un récipient mystérieux pouvant faire évoluer un certain Pokémon. Il est ébréché, mais on y fait du bon thé.",
                "de": "Diese spezielle Kanne löst bei einem bestimmten Pokémon die Entwicklung aus. Sie weist zwar Löcher auf, aber das wirkt sich nicht negativ auf den Tee aus.",
            ]),
        "auspicious-armor": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "축복받은갑옷", "en": "Auspicious Armor", "ja": "イワイノヨロイ", "es": "Armadura Auspiciosa", "fr": "Armure de la Fortune", "de": "Glorienrüstung"],
            texts: [
                "ko": "상서로운 기운이 감도는 갑옷. 어떤 포켓몬에게 주면 진화한다.",
                "en": "Armor brimming with an auspicious aura. A certain Pokémon evolves when it is given this armor.",
                "ja": "めでたい　オーラが　ただよう　よろい。あるポケモンに　あたえると　しんかする。",
                "es": "Una armadura que rebosa un aura de buen augurio. Cierto Pokémon evoluciona si se le da esta armadura.",
                "fr": "Une armure qui déborde d'une aura de bon augure. Un certain Pokémon évolue si on la lui donne.",
                "pt": "Uma armadura repleta de uma aura auspiciosa. Certo Pokémon evolui ao receber esta armadura.",
                "de": "Eine Rüstung voller glückverheißender Aura. Ein bestimmtes Pokémon entwickelt sich, wenn es sie bekommt.",
                "ru": "Доспехи, наполненные благоприятной аурой. Некоторый покемон эволюционирует, если ему их дать.",
            ]),
        "malicious-armor": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "저주받은갑옷", "en": "Malicious Armor", "ja": "ノロイノヨロイ", "es": "Armadura Maldita", "fr": "Armure de la Rancune", "de": "Fluchrüstung"],
            texts: [
                "ko": "악의가 감도는 갑옷. 어떤 포켓몬에게 주면 진화한다.",
                "en": "Armor brimming with a malicious aura. A certain Pokémon evolves when it is given this armor.",
                "ja": "あくいが　ただよう　よろい。あるポケモンに　あたえると　しんかする。",
                "es": "Una armadura que rebosa un aura maliciosa. Cierto Pokémon evoluciona si se le da esta armadura.",
                "fr": "Une armure qui déborde d'une aura malveillante. Un certain Pokémon évolue si on la lui donne.",
                "pt": "Uma armadura repleta de uma aura maliciosa. Certo Pokémon evolui ao receber esta armadura.",
                "de": "Eine Rüstung voller böser Aura. Ein bestimmtes Pokémon entwickelt sich, wenn es sie bekommt.",
                "ru": "Доспехи, наполненные злой аурой. Некоторый покемон эволюционирует, если ему их дать.",
            ]),
        "galarica-cuff": Entry(appOriginalLanguages: [],
            names: ["ko": "가라두구팔찌", "en": "Galarica Cuff", "ja": "ガラナツブレス", "es": "Brazal Galanuez", "fr": "Bracelet Galanoa", "de": "Galarnuss-Reif"],
            texts: [
                "ko": "가라두구가지를 엮어서 만든 팔찌. 가라르지방의 야돈에게 채워주면 기뻐한다.",
                "en": "A cuff made from woven-together Galarica Twigs. Giving it to Galarian Slowpoke makes the Pokémon very happy.",
                "ja": "ガラナツのえだを　あみこんだ　ブレスレット。　ガラルちほうの　ヤドンに　つけてあげると　よろこぶ。",
                "es": "Un brazalete hecho de Ramas de Galanuez trenzadas. Los Slowpoke de Galar se ponen contentísimos si lo reciben como regalo.",
                "fr": "Un bracelet confectionné à partir de Branches Galanoa. Les Ramoloss de Galar adorent en porter.",
                "de": "Ein Armreif, der aus Galarnuss-Zweigen gewoben wird. Galar-Flegmon freuen sich, wenn sie diesen anlegen dürfen.",
            ]),
        "galarica-wreath": Entry(appOriginalLanguages: [],
            names: ["ko": "가라두구머리장식", "en": "Galarica Wreath", "ja": "ガラナツリース", "es": "Corona Galanuez", "fr": "Couronne Galanoa", "de": "Galarnuss-Kranz"],
            texts: [
                "ko": "가라두구가지를 엮어서 만든 머리 장식. 가라르지방의 야돈에게 씌워주면 기뻐한다.",
                "en": "A wreath made from woven-together Galarica Twigs. Placing it on the head of a Galarian Slowpoke makes the Pokémon very happy.",
                "ja": "ガラナツのえだを　あみこんだ　かんむり。　ガラルちほうの　ヤドンに　かぶせてあげると　よろこぶ。",
                "es": "Una corona hecha de Ramas de Galanuez trenzadas. Los Slowpoke de Galar se ponen contentísimos cuando la llevan puesta.",
                "fr": "Une couronne confectionnée à partir de Branches Galanoa. Les Ramoloss de Galar adorent en porter.",
                "de": "Ein Kranz, der aus Galarnuss-Zweigen gewoben wurde. Galar-Flegmon freuen sich, wenn sie diesen tragen dürfen.",
            ]),
        "unremarkable-teacup": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "범작찻잔", "en": "Unremarkable Teacup", "ja": "ボンサクのちゃわん", "es": "Cuenco Mediocre", "fr": "Bol Médiocre", "de": "Simple Teeschale"],
            texts: [
                "ko": "별다를 것 없는 평범한 찻잔. 어떤 포켓몬이 깃들면 진화한다.",
                "en": "An unremarkable, ordinary-looking teacup. A certain Pokémon evolves when it takes up residence in it.",
                "ja": "とくに　かわったところの　ない　ふつうの　ちゃわん。あるポケモンが　やどると　しんかする。",
                "es": "Una taza de té corriente y sin nada especial. Cierto Pokémon evoluciona si se instala en ella.",
                "fr": "Une tasse à thé ordinaire, sans rien de remarquable. Un certain Pokémon évolue s'il s'y installe.",
                "pt": "Uma xícara de chá comum, sem nada de especial. Certo Pokémon evolui ao se instalar nela.",
                "de": "Eine gewöhnliche, unscheinbare Teetasse. Ein bestimmtes Pokémon entwickelt sich, wenn es sich darin einnistet.",
                "ru": "Обычная, ничем не примечательная чайная чашка. Некоторый покемон эволюционирует, если поселится в ней.",
            ]),
        "masterpiece-teacup": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "걸작찻잔", "en": "Masterpiece Teacup", "ja": "ケッサクのちゃわん", "es": "Cuenco Exquisito", "fr": "Bol Exceptionnel", "de": "Edle Teeschale"],
            texts: [
                "ko": "정교하게 만들어진 걸작 찻잔. 어떤 포켓몬이 깃들면 진화한다.",
                "en": "A masterpiece of a teacup, exquisitely made. A certain Pokémon evolves when it takes up residence in it.",
                "ja": "せいこうに　つくられた　けっさくの　ちゃわん。あるポケモンが　やどると　しんかする。",
                "es": "Una taza de té que es una obra maestra, de factura exquisita. Cierto Pokémon evoluciona si se instala en ella.",
                "fr": "Une tasse à thé qui est un chef-d'œuvre, d'une facture exquise. Un certain Pokémon évolue s'il s'y installe.",
                "pt": "Uma xícara de chá que é uma obra-prima, feita com requinte. Certo Pokémon evolui ao se instalar nela.",
                "de": "Eine meisterhaft gefertigte Teetasse. Ein bestimmtes Pokémon entwickelt sich, wenn es sich darin einnistet.",
                "ru": "Чайная чашка-шедевр, изысканной работы. Некоторый покемон эволюционирует, если поселится в ней.",
            ]),
        "metal-alloy": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "복합금속", "en": "Metal Alloy", "ja": "ふくごうきんぞく", "es": "Metal Compuesto", "fr": "Métal Composite", "de": "Legierungsmetall"],
            texts: [
                "ko": "신기한 금속 합금. 어떤 포켓몬이 이 합금에 닿으면 진화한다.",
                "en": "A peculiar metal alloy. A certain Pokémon evolves when it is exposed to this alloy.",
                "ja": "ふしぎな　きんぞくの　ごうきん。あるポケモンが　ふれると　しんかする。",
                "es": "Una extraña aleación de metales. Cierto Pokémon evoluciona si se expone a esta aleación.",
                "fr": "Un étrange alliage métallique. Un certain Pokémon évolue s'il y est exposé.",
                "pt": "Uma estranha liga metálica. Certo Pokémon evolui ao ser exposto a esta liga.",
                "de": "Eine seltsame Metalllegierung. Ein bestimmtes Pokémon entwickelt sich, wenn es ihr ausgesetzt wird.",
                "ru": "Необычный металлический сплав. Некоторый покемон эволюционирует, если подвергнется его воздействию.",
            ]),
        "peat-block": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "피트블록", "en": "Peat Block", "ja": "ピートブロック", "es": "Bloque de Turba", "fr": "Bloc de Tourbe", "de": "Torfblock"],
            texts: [
                "ko": "신비한 에너지가 가득한 이탄 덩어리. 어떤 포켓몬이 이 덩어리에 닿으면 진화한다.",
                "en": "A block of peat brimming with mysterious energy. A certain Pokémon evolves when it is exposed to this block.",
                "ja": "ふしぎな　エネルギーに　みちた　でいたんの　かたまり。あるポケモンが　ふれると　しんかする。",
                "es": "Un bloque de turba lleno de energía misteriosa. Cierto Pokémon evoluciona si se expone a este bloque.",
                "fr": "Un bloc de tourbe plein d'énergie mystérieuse. Un certain Pokémon évolue s'il y est exposé.",
                "pt": "Um bloco de turfa repleto de energia misteriosa. Certo Pokémon evolui ao ser exposto a este bloco.",
                "de": "Ein Torfblock voll geheimnisvoller Energie. Ein bestimmtes Pokémon entwickelt sich, wenn es ihm ausgesetzt wird.",
                "ru": "Брикет торфа, полный таинственной энергии. Некоторый покемон эволюционирует, если подвергнется его воздействию.",
            ]),
        "black-augurite": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "검은휘석", "en": "Black Augurite", "ja": "くろのきせき", "es": "Mineral Negro", "fr": "Obsidienne", "de": "Schwarzaugit"],
            texts: [
                "ko": "검게 빛나는 신기한 광물. 어떤 포켓몬이 이 광물에 닿으면 진화한다.",
                "en": "A peculiar black mineral that gleams. A certain Pokémon evolves when it is exposed to this mineral.",
                "ja": "くろく　かがやく　ふしぎな　こうぶつ。あるポケモンが　ふれると　しんかする。",
                "es": "Un extraño mineral negro y brillante. Cierto Pokémon evoluciona si se expone a este mineral.",
                "fr": "Un étrange minéral noir et brillant. Un certain Pokémon évolue s'il y est exposé.",
                "pt": "Um estranho mineral preto e reluzente. Certo Pokémon evolui ao ser exposto a este mineral.",
                "de": "Ein seltsames, schwarz glänzendes Mineral. Ein bestimmtes Pokémon entwickelt sich, wenn es ihm ausgesetzt wird.",
                "ru": "Необычный блестящий чёрный минерал. Некоторый покемон эволюционирует, если подвергнется его воздействию.",
            ]),
        "scroll-of-darkness": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "악의 족자", "en": "Scroll of Darkness", "ja": "あくのかけじく", "es": "Manuscrito Sombras", "fr": "Rouleau des Ténèbres", "de": "Unlicht-Schriftrolle"],
            texts: [
                "ko": "악의 탑의 가르침이 적힌 두루마리. 어떤 포켓몬이 읽으면 진화한다.",
                "en": "A scroll that records the teachings of the Tower of Darkness. A certain Pokémon evolves when it studies it.",
                "ja": "あくのとうの　おしえが　かかれた　まきもの。あるポケモンが　よむと　しんかする。",
                "es": "Un pergamino con las enseñanzas de la Torre Oscura. Cierto Pokémon evoluciona si lo estudia.",
                "fr": "Un parchemin consignant les enseignements de la Tour Obscure. Un certain Pokémon évolue s'il l'étudie.",
                "pt": "Um pergaminho com os ensinamentos da Torre da Escuridão. Certo Pokémon evolui ao estudá-lo.",
                "de": "Eine Schriftrolle mit den Lehren des Turms der Finsternis. Ein bestimmtes Pokémon entwickelt sich, wenn es sie studiert.",
                "ru": "Свиток с учением Башни Тьмы. Некоторый покемон эволюционирует, если изучит его.",
            ]),
        "scroll-of-waters": Entry(appOriginalLanguages: ["ko", "en", "ja", "es", "fr", "pt", "de", "ru"],
            names: ["ko": "물의 족자", "en": "Scroll of Waters", "ja": "みずのかけじく", "es": "Manuscrito Aguas", "fr": "Rouleau de l'Eau", "de": "Wasser-Schriftrolle"],
            texts: [
                "ko": "물의 탑의 가르침이 적힌 두루마리. 어떤 포켓몬이 읽으면 진화한다.",
                "en": "A scroll that records the teachings of the Tower of Waters. A certain Pokémon evolves when it studies it.",
                "ja": "みずのとうの　おしえが　かかれた　まきもの。あるポケモンが　よむと　しんかする。",
                "es": "Un pergamino con las enseñanzas de la Torre Agua. Cierto Pokémon evoluciona si lo estudia.",
                "fr": "Un parchemin consignant les enseignements de la Tour d'Eau. Un certain Pokémon évolue s'il l'étudie.",
                "pt": "Um pergaminho com os ensinamentos da Torre da Água. Certo Pokémon evolui ao estudá-lo.",
                "de": "Eine Schriftrolle mit den Lehren des Wasserturms. Ein bestimmtes Pokémon entwickelt sich, wenn es sie studiert.",
                "ru": "Свиток с учением Башни Воды. Некоторый покемон эволюционирует, если изучит его.",
            ]),
        "oval-stone": Entry(appOriginalLanguages: [],
            names: ["ko": "동글동글돌", "en": "Oval Stone", "ja": "まんまるいし", "es": "Piedra Oval", "fr": "Pierre Ovale", "de": "Ovaler Stein"],
            texts: [
                "ko": "어느 특정 포켓몬을 진화시키는 이상한 돌. 구슬처럼 둥글다.",
                "en": "A peculiar stone that can make certain species of Pokémon evolve. It’s as round as a Pokémon Egg.",
                "ja": "ある　とくていの　ポケモンを　しんかさせる　ふしぎな　いし。　たまのように　まるい。",
                "es": "Una piedra peculiar que hace evolucionar a algunos Pokémon. Tiene forma de huevo.",
                "fr": "Une pierre étrange qui fait évoluer certaines espèces de Pokémon. Elle a la forme d’un œuf.",
                "de": "Dieser besondere, eiförmige Stein hilft manchen Pokémon bei ihrer Entwicklung.",
            ]),
        "razor-claw": Entry(appOriginalLanguages: [],
            names: ["ko": "예리한손톱", "en": "Razor Claw", "ja": "するどいツメ", "es": "Garra Afilada", "fr": "Griffe Rasoir", "de": "Scharfklaue"],
            texts: [
                "ko": "날카롭고 뾰족한 손톱. 지니게 하면 기술이 급소에 맞기 쉬워진다.",
                "en": "An item to be held by a Pokémon. This sharply hooked claw increases the holder’s critical-hit ratio.",
                "ja": "するどく　とがった　ツメ。　もたせると　わざが　きゅうしょに　あたりやすくなる。",
                "es": "Aumenta la probabilidad de que el Pokémon que la lleve consiga un golpe crítico.",
                "fr": "Objet à tenir. Une griffe crochue et pointue augmentant le taux de critiques.",
                "de": "Ein Item zum Tragen. Die scharfe Klaue erhöht die Volltrefferquote des Trägers.",
            ]),
        "razor-fang": Entry(appOriginalLanguages: [],
            names: ["ko": "예리한이빨", "en": "Razor Fang", "ja": "するどいキバ", "es": "Colmillo Agudo", "fr": "Croc Rasoir", "de": "Scharfzahn"],
            texts: [
                "ko": "날카롭고 뾰족한 이빨. 지니게 하면 데미지를 줬을 때 풀죽게 하기도 한다.",
                "en": "An item to be held by a Pokémon. When the holder successfully inflicts damage, the target may also flinch.",
                "ja": "するどく　とがった　キバ。　もたせると　ダメージを　あたえたとき　ひるませることが　ある。",
                "es": "Si lo lleva un Pokémon, puede amedrentar al objetivo al infligirle daño.",
                "fr": "Objet à tenir. Peut apeurer l’ennemi quand le porteur lui inflige des dégâts.",
                "de": "Ein Item zum Tragen. Verursacht der Träger Schaden, schreckt das Ziel eventuell zurück.",
            ]),
        "strawberry-sweet": Entry(appOriginalLanguages: [],
            names: ["ko": "딸기사탕공예", "en": "Strawberry Sweet", "ja": "いちごアメざいく", "es": "Confite Fresa", "fr": "Fraise en Sucre", "de": "Zucker-Erdbeere"],
            texts: [
                "ko": "딸기 모양의 사탕공예. 마빌크에게 지니게 하면 빙빙 돌며 기뻐한다.",
                "en": "A strawberry-shaped sweet. When a Milcery holds this, it will spin around happily.",
                "ja": "いちごの　かたちを　した　アメざいく。　マホミルに　もたせてあげると　くるくる　まわって　よろこぶ。",
                "es": "Figura de caramelo con forma de fresa. Al dárselo a Milcery, se pone a girar rebosante de alegría.",
                "fr": "Un bonbon en forme de fraise. Quand on le donne à un Crèmy, il danse de bonheur.",
                "de": "Zuckerwerk in Form einer Erdbeere. Gibt man es Hokumil zum Tragen, dreht es sich vor Freude im Kreis.",
            ]),
        "metal-coat": Entry(appOriginalLanguages: [],
            names: ["ko": "금속코트", "en": "Metal Coat", "ja": "メタルコート", "es": "Revest. Metálico", "fr": "Peau Métal", "de": "Metallmantel"],
            texts: [
                "ko": "특수한 금속 장막. 지니게 하면 강철타입 기술의 위력이 올라간다.",
                "en": "An item to be held by a Pokémon. It’s a special metallic film that can boost the power of Steel-type moves.",
                "ja": "とくしゅな　きんぞくの　まく。　もたせると　はがねタイプの　わざの　いりょくが　あがる。",
                "es": "Película metálica que fortalece los ataques de tipo Acero. Debe llevarlo un Pokémon.",
                "fr": "Objet à tenir. Une pellicule métallique spéciale qui augmente la puissance des capacités de type Acier.",
                "de": "Ein Item, das einem Pokémon zum Tragen gegeben werden kann. Es verstärkt Attacken vom Typ Stahl.",
            ]),
        "kings-rock": Entry(appOriginalLanguages: [],
            names: ["ko": "왕의징표석", "en": "King’s Rock", "ja": "おうじゃのしるし", "es": "Roca del Rey", "fr": "Roche Royale", "de": "King-Stein"],
            texts: [
                "ko": "지니게 하면 공격해서 데미지를 줄 때 상대를 풀죽이기도 한다.",
                "en": "An item to be held by a Pokémon. When the holder successfully inflicts damage, the target may also flinch.",
                "ja": "もたせると　こうげきして　ダメージを　あたえたときに　あいてを　ひるませることが　ある。",
                "es": "El Pokémon que la lleva puede amedrentar al Pokémon al que le inflige daño.",
                "fr": "Objet à tenir. Peut apeurer l’ennemi lorsque le porteur lui inflige des dégâts.",
                "de": "Gibst du es einem Pokémon zum Tragen, lässt es mit seinem Angriff das Ziel gelegentlich zurückschrecken.",
            ]),
        "dragon-scale": Entry(appOriginalLanguages: [],
            names: ["ko": "용의비늘", "en": "Dragon Scale", "ja": "りゅうのウロコ", "es": "Escama Dragón", "fr": "Écaille Draco", "de": "Drachenschuppe"],
            texts: [
                "ko": "단단하고 튼튼한 비늘. 드래곤타입의 포켓몬이 지니고 있는 경우가 있다.",
                "en": "A very tough and inflexible scale. Dragon-type Pokémon may be holding this item when caught.",
                "ja": "かたくて　じょうぶな　ウロコ。　ドラゴンタイプの　ポケモンが　もっていることが　ある。",
                "es": "Una gruesa y resistente escama que pueden llevar los Pokémon de tipo Dragón cuando son capturados.",
                "fr": "Une écaille épaisse et dure, parfois tenue par les Pokémon de type Dragon quand ils sont attrapés.",
                "de": "Eine dicke und starke Haut. Drachen-Pokémon tragen dieses Item gern bei sich.",
            ]),
        "up-grade": Entry(appOriginalLanguages: [],
            names: ["ko": "업그레이드", "en": "Upgrade", "ja": "アップグレード", "es": "Mejora", "fr": "Améliorator", "de": "Upgrade"],
            texts: [
                "ko": "안에 여러 가지 정보가 가득한 투명한 기계다. 실프주식회사 제품.",
                "en": "A transparent device somehow filled with all sorts of data. It was produced by Silph Co.",
                "ja": "なかに　いろんな　じょうほうが　つまった　とうめいな　きかい。　シルフ　カンパニーせい。",
                "es": "Peculiar dispositivo fabricado en Silph S. A. que contiene todo tipo de datos.",
                "fr": "Un dispositif transparent rempli de données diverses et variées. Fabriqué par la Sylphe SARL.",
                "de": "Ein durchsichtiges Gerät. Es enthält alle möglichen Daten. Hergestellt von der Silph Company.",
            ]),
        "dubious-disc": Entry(appOriginalLanguages: [],
            names: ["ko": "괴상한패치", "en": "Dubious Disc", "ja": "あやしいパッチ", "es": "Disco Extraño", "fr": "CD Douteux", "de": "Dubiosdisc"],
            texts: [
                "ko": "안에 괴상한 정보가 가득한 투명한 기계다. 제작자 불명.",
                "en": "A transparent device overflowing with dubious data. Its producer is unknown.",
                "ja": "なかに　あやしい　じょうほうが　つまった　とうめいな　きかい。　せいさくしゃは　ふめい。",
                "es": "Dispositivo transparente que contiene datos misteriosos. Es de fabricante desconocido.",
                "fr": "Un appareil transparent rempli de données douteuses. Son fabricant n’est pas connu.",
                "de": "Eine Scheibe mit seltsamen Daten. Ihr Ursprung ist unbekannt.",
            ]),
        "electirizer": Entry(appOriginalLanguages: [],
            names: ["ko": "에레키부스터", "en": "Electirizer", "ja": "エレキブースター", "es": "Electrizador", "fr": "Électriseur", "de": "Stromisierer"],
            texts: [
                "ko": "엄청난 전기의 에너지가 비축되어 있는 상자. 어떤 포켓몬이 좋아하는 물건이다.",
                "en": "A box packed with a tremendous amount of electric energy. It’s loved by a certain Pokémon.",
                "ja": "とてつもない　でんきの　エネルギーが　たくわえられている　はこ。　ある　ポケモンが　このんでいる。",
                "es": "Este dispositivo contiene una gran cantidad de energía eléctrica. Cierto Pokémon lo adora.",
                "fr": "Une boîte remplie d’une énorme quantité d’énergie électrique. Appréciée d’un certain Pokémon.",
                "de": "Eine Schachtel mit elektrischer Energie. Das Lieblingsstück eines bestimmten Pokémon.",
            ]),
        "magmarizer": Entry(appOriginalLanguages: [],
            names: ["ko": "마그마부스터", "en": "Magmarizer", "ja": "マグマブースター", "es": "Magmatizador", "fr": "Magmariseur", "de": "Magmaisierer"],
            texts: [
                "ko": "엄청난 마그마의 에너지가 비축되어 있는 상자. 어떤 포켓몬이 좋아하는 물건이다.",
                "en": "A box packed with a tremendous amount of magma energy. It’s loved by a certain Pokémon.",
                "ja": "とてつもない　マグマの　エネルギーが　たくわえられている　はこ。　ある　ポケモンが　このんでいる。",
                "es": "Esta caja contiene una enorme cantidad de energía magmática. Cierto Pokémon la adora.",
                "fr": "Une boîte remplie d’une énorme quantité d’énergie magmatique. Appréciée d’un certain Pokémon.",
                "de": "Eine Schachtel mit Magma-Energie. Das Lieblingsstück eines bestimmten Pokémon.",
            ]),
        "protector": Entry(appOriginalLanguages: [],
            names: ["ko": "프로텍터", "en": "Protector", "ja": "プロテクター", "es": "Protector", "fr": "Protecteur", "de": "Schützer"],
            texts: [
                "ko": "무언가의 프로텍터. 매우 단단하고 무겁다. 어떤 포켓몬이 좋아하는 물건이다.",
                "en": "A protective item of some sort. It is extremely stiff and heavy. It’s loved by a certain Pokémon.",
                "ja": "なにかの　プロテクター。　とても　かたくて　おもい。　ある　ポケモンが　このんでいる。",
                "es": "Dispositivo de protección muy pesado. Cierto Pokémon lo adora.",
                "fr": "Un objet protecteur très dur et très lourd, apprécié d’un certain Pokémon.",
                "de": "Ein schützendes Item. Steif und schwer. Das Lieblingsstück eines bestimmten Pokémon.",
            ]),
        "reaper-cloth": Entry(appOriginalLanguages: [],
            names: ["ko": "영계의천", "en": "Reaper Cloth", "ja": "れいかいのぬの", "es": "Tela Terrible", "fr": "Tissu Fauche", "de": "Düsterumhang"],
            texts: [
                "ko": "무섭고 강한 영력이 담겨 있는 천. 어떤 포켓몬이 좋아하는 물건이다.",
                "en": "A cloth imbued with horrifyingly strong spiritual energy. It’s loved by a certain Pokémon.",
                "ja": "おそろしく　つよい　れいりょくが　こめられている　ぬの。　ある　ポケモンが　このんでいる。",
                "es": "Tela imbuida de una energía espiritual muy potente. Cierto Pokémon la adora.",
                "fr": "Un tissu imprégné d’une énergie spirituelle horriblement puissante. Apprécié d’un certain Pokémon.",
                "de": "Ein Stoffumhang mit geistiger Energie. Das Lieblingsstück eines bestimmten Pokémon.",
            ]),
        "deep-sea-tooth": Entry(appOriginalLanguages: [],
            names: ["ko": "심해의이빨", "en": "Deep Sea Tooth", "ja": "しんかいのキバ", "es": "Diente Marino", "fr": "Dent Océan", "de": "Abysszahn"],
            texts: [
                "ko": "진주몽에게 지니게 하면 특수공격이 올라가는 이빨. 날카로운 은색으로 빛난다.",
                "en": "An item to be held by Clamperl. This fang gleams a sharp silver and raises the holder’s Sp. Atk stat.",
                "ja": "パールルに　もたせると　とくこうが　あがる　キバ。　するどく　ぎんいろに　ひかる。",
                "es": "Tiene el brillo afilado de la plata y debe llevarlo Clamperl. Sube el Ataque Especial.",
                "fr": "Objet à faire tenir à Coquiperl. Une dent de couleur argent qui augmente son Attaque Spéciale.",
                "de": "Ein Item, das von Perlu getragen werden kann. Es schimmert silbern und hebt den Spezial-Angriff.",
            ]),
        "deep-sea-scale": Entry(appOriginalLanguages: [],
            names: ["ko": "심해의비늘", "en": "Deep Sea Scale", "ja": "しんかいのウロコ", "es": "Escama Marina", "fr": "Écaille Océan", "de": "Abyssschuppe"],
            texts: [
                "ko": "진주몽에게 지니게 하면 특수방어가 올라가는 비늘. 연한 분홍색으로 빛난다.",
                "en": "An item to be held by Clamperl. This scale shines with a faint pink and raises the holder’s Sp. Def stat.",
                "ja": "パールルに　もたせると　とくぼうが　あがる　ウロコ。　うすい　ピンクいろに　ひかる。",
                "es": "Tiene un débil brillo rosado y debe llevarla Clamperl. Sube la Defensa Especial.",
                "fr": "Objet à faire tenir à Coquiperl. Une écaille de couleur rose qui augmente sa Défense Spéciale.",
                "de": "Ein Item, das von Perlu getragen werden kann. Es schimmert pink und hebt die Spezial-Verteidigung.",
            ]),
        "sachet": Entry(appOriginalLanguages: [],
            names: ["ko": "향기주머니", "en": "Sachet", "ja": "においぶくろ", "es": "Saquito Fragante", "fr": "Sachet Senteur", "de": "Duftbeutel"],
            texts: [
                "ko": "살짝 강렬한 향기가 나는 향료를 채운 주머니. 어떤 포켓몬이 좋아하는 물건이다.",
                "en": "A sachet filled with fragrant perfumes that are just slightly too overwhelming. Yet it’s loved by a certain Pokémon.",
                "ja": "ちょっと　きつめの　かおりをだす　こうりょうを　つめた　ふくろ。　ある　ポケモンが　このんでいる。",
                "es": "Un saquito lleno de sustancias aromáticas cuyo perfume resulta abrumador, pero que a cierto Pokémon le encanta.",
                "fr": "Un sachet d’herbes et d’épices, au parfum trop marqué pour beaucoup, mais néanmoins apprécié d’un certain Pokémon.",
                "de": "Ein mit Parfüm gefüllter Beutel, der einen penetranten Duft verströmt und bei einer bestimmten Pokémon-Art sehr beliebt ist.",
            ]),
        "whipped-dream": Entry(appOriginalLanguages: [],
            names: ["ko": "휘핑팝", "en": "Whipped Dream", "ja": "ホイップポップ", "es": "Dulce de Nata", "fr": "Chantibonbon", "de": "Sahnehäubchen"],
            texts: [
                "ko": "풍성하게 거품을 낸 살짝 달콤한 크림. 어떤 포켓몬이 좋아한다.",
                "en": "A soft and sweet treat made of fluffy, puffy, whipped, and whirled cream. It’s loved by a certain Pokémon.",
                "ja": "ふんわり　ふわふわに　あわだてた　ほんのり　あまい　クリーム。　ある　ポケモンが　このんでいる。",
                "es": "Un dulce a base de suave y esponjosa nata montada. A cierto Pokémon le encanta.",
                "fr": "Une crème sucrée qui fond dans la bouche, légère comme un nuage. Elle est appréciée d’un certain Pokémon.",
                "de": "Ein lockeres, leicht süßliches Häubchen aus Schlagsahne, das bei einer bestimmten Pokémon-Art sehr beliebt ist.",
            ]),
        "prism-scale": Entry(appOriginalLanguages: [],
            names: ["ko": "고운비늘", "en": "Prism Scale", "ja": "きれいなウロコ", "es": "Escama Bella", "fr": "Bel’Écaille", "de": "Schönschuppe"],
            texts: [
                "ko": "어느 특정 포켓몬을 진화시키는 이상한 비늘. 무지갯빛으로 빛나고 있다.",
                "en": "A mysterious scale that causes a certain Pokémon to evolve. It shines in rainbow colors.",
                "ja": "ある　とくていの　ポケモンを　しんかさせる　ふしぎな　ウロコ。　にじいろに　かがやいている。",
                "es": "Curiosa escama que hace evolucionar a cierto Pokémon. Brilla con los colores del arcoíris.",
                "fr": "Une écaille étrange qui fait évoluer une certaine espèce de Pokémon. Elle a une couleur arc-en-ciel.",
                "de": "Eine seltsame Schuppe, durch die sich ein bestimmtes Pokémon entwickelt. Sie funkelt in den Farben des Regenbogens.",
            ]),
        "venusaurite": Entry(appOriginalLanguages: [],
            names: ["ko": "이상해꽃나이트", "en": "Venusaurite", "ja": "フシギバナイト", "es": "Venusaurita", "fr": "Florizarrite", "de": "Bisaflornit"],
            texts: [
                "ko": "이상해꽃에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.",
                "en": "One of a variety of mysterious Mega Stones. Have Venusaur hold it, and this stone will enable it to Mega Evolve during battle.",
                "ja": "フシギバナに　もたせておくと　たたかいのとき　メガシンカが　できる　ふしぎな　メガストーンの　いっしゅ。",
                "es": "Una de las misteriosas Megapiedras. Permite megaevolucionar a Venusaur en combate.",
                "fr": "Une variété de Méga-Gemme. Tenue par un Florizarre, elle lui permet de méga-évoluer durant un combat.",
                "de": "Einer der mysteriösen Mega-Steine. Wird er von einem Bisaflor getragen, kann es im Kampf eine Mega-Entwicklung durchführen.",
            ]),
        "charizardite-x": Entry(appOriginalLanguages: [],
            names: ["ko": "리자몽나이트X", "en": "Charizardite X", "ja": "リザードナイトＸ", "es": "Charizardita X", "fr": "Dracaufite X", "de": "Gluraknit X"],
            texts: [
                "ko": "리자몽에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.",
                "en": "One of a variety of mysterious Mega Stones. Have Charizard hold it, and this stone will enable it to Mega Evolve during battle.",
                "ja": "リザードンに　もたせておくと　たたかいのとき　メガシンカが　できる　ふしぎな　メガストーンの　いっしゅ。",
                "es": "Una de las misteriosas Megapiedras. Permite megaevolucionar a Charizard en combate.",
                "fr": "Une variété de Méga-Gemme. Tenue par un Dracaufeu, elle lui permet de méga-évoluer durant un combat.",
                "de": "Einer der mysteriösen Mega-Steine. Wird er von einem Glurak getragen, kann es im Kampf eine Mega-Entwicklung durchführen.",
