        "blastoisinite": Entry(appOriginalLanguages: [],
            names: ["ko": "거북왕나이트", "en": "Blastoisinite", "ja": "カメックスナイト", "es": "Blastoisita", "fr": "Tortankite", "de": "Turtoknit"],
            texts: [
