        "beedrillite": Entry(appOriginalLanguages: [],
            names: ["ko": "독침붕나이트", "en": "Beedrillite", "ja": "スピアナイト", "es": "Beedrillita", "fr": "Dardargnite", "de": "Bibornit"],
            texts: [
                "ko": "독침붕에게 지니게 하면 배틀할 때 메가진화할 수 있는 신비한 메가스톤의 일종.",
